python3 -I -B -c 'import os, pathlib, runpy, subprocess, sys
env = {k: v for k, v in os.environ.items() if not k.upper().startswith("GIT_")}
try:
    root = subprocess.check_output(["git", "rev-parse", "--show-toplevel"], env=env, text=True, stderr=subprocess.DEVNULL, timeout=2).rstrip("\n")
except (OSError, subprocess.SubprocessError):
    sys.exit("hook bootstrap: cannot resolve Git root")
script = pathlib.Path(root) / "scripts/ai/harness.py"
if not script.is_file() or not script.resolve().is_relative_to(pathlib.Path(root).resolve()):
    sys.exit("hook bootstrap: project hook script missing or outside Git root")
sys.argv = [str(script), "hook"]
runpy.run_path(str(script), run_name="__main__")'

